const svg=$('#mapSvg');let drag=null;const mq=matchMedia('(max-width:720px)');function viewport(){svg.setAttribute('viewBox',mq.matches?'150 30 650 760':'0 0 900 680');$('#layerDetails').open=!mq.matches;if(D)renderMap()}mq.addEventListener('change',viewport);viewport();function mapPoint(e){let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;let p=mapPoint(e);drag={id:e.pointerId,x:p.x,y:p.y,camera:{...state.camera},moved:false};});svg.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;let p=mapPoint(e),dx=p.x-drag.x,dy=p.y-drag.y;if(Math.hypot(dx,dy)>5){drag.moved=true;svg.setPointerCapture(e.pointerId);svg.classList.add('dragging');state.camera.x=Math.max(-900*state.camera.zoom+100,Math.min(800,drag.camera.x+dx));state.camera.y=Math.max(-680*state.camera.zoom+100,Math.min(580,drag.camera.y+dy));renderMap()}});function endDrag(){if(!drag)return;if(drag.moved){suppressClick=true;setTimeout(()=>suppressClick=false,50);save(true)}drag=null;svg.classList.remove('dragging')}svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointercancel',endDrag);svg.addEventListener('keydown',e=>{if(e.target!==svg)return;if(['+','=','-'].includes(e.key)){e.preventDefault();zoomBy(e.key==='-'?-.3:.3)}let moves={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]};if(moves[e.key]){e.preventDefault();state.camera.x+=moves[e.key][0];state.camera.y+=moves[e.key][1];renderMap();save(true)}});
async function request(url,check=validateData){let r=await fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);return check(await r.json())}
async function load(){let status=$('#dataStatus');$('#refresh').disabled=true;status.textContent='Loading current catalogue…';let fresh=false,hadData=!!D;try{const local=/^(www\.)?xsonomy\.com$/.test(location.hostname);D=await request(local?'/data/landscape.json':'https://xsonomy.com/data/landscape.json');fresh=true}catch{if(!D){try{if(document.body.dataset.snapshot==='false')throw Error('No snapshot');D=await request('./snapshot.json')}catch{status.innerHTML='Catalogue unavailable. Please retry.';$('#refresh').disabled=false;return}}}status.classList.toggle('notice',!fresh);let date=new Date(D.generatedAt);status.textContent=(fresh?'Current catalogue':hadData?'Last loaded data — refresh unavailable':'Offline snapshot — refresh unavailable')+' · '+(Number.isNaN(date.getTime())?'date unavailable':date.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}));$('#refresh').disabled=false;render();loadInvestors().then(()=>{if(D)render()})}
// ---- Investor research layer -------------------------------------------------
// The export at /data/landscape-investors.json is a separate organisation class: approved
// research records with a published city-level location, an evidence URL and a review date.
// Everything below reads that payload; counts, labels and caveats come from the file itself.
const money=n=>Number.isFinite(n)?n.toLocaleString('en-GB'):'—';
const safeUrl=u=>/^https?:\/\//i.test(String(u||''))?String(u):'';
const FOCUS_ORDER=['UAV','UAV components','C-UAS','Autonomy','Components','Sensors','Cyber','Space'];
const byFocus=(a,b)=>{let i=FOCUS_ORDER.indexOf(a),j=FOCUS_ORDER.indexOf(b);return (i<0?99:i)-(j<0?99:j)||a.localeCompare(b)};
function invCountLine(list){let n=list.length,l=invLocations(list);return n?`${n} investor${n===1?'':'s'} · ${l} matching location${l===1?'':'s'}`:'No investors match'}
function invStatusText(){if(vStatus==='loading'&&!V)return 'Loading investor records…';if(vStatus==='error')return 'Investor records unavailable — the company layer is unaffected.';if(!V)return '';let d=new Date(V.generatedAt),loc=V.investors.reduce((n,i)=>n+i.locations.length,0);return `${vStatus==='stale'?'Last loaded investor records — refresh unavailable':`${V.investors.length} approved investor records`} · ${loc} published locations · ${Number.isNaN(d.getTime())?'date unavailable':d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}`}
// One marker per matching published location; they all carry the same investor identity, so
// selecting any of them opens the one record. Names are dropped when the map gets crowded.
function invMarkers(){let out=[];for(let i of invResults())for(let l of investorLocations(i,state))out.push({id:i.slug,key:`${i.slug}@${l.country}:${l.city}`,investor:i.name,city:l.city,country:l.country,kind:l.kind,lon:l.longitude,lat:l.latitude});return out.map(m=>({...m,label:out.length<=14?m.investor:''}))}
function invCards(list){if(!V)return '<div class="empty-card">Investor records could not be loaded.<p class="muted">Company data on this page is unaffected.</p><button data-retry-investors>Retry investor records</button></div>';return list.length?list.map(i=>{let locs=investorLocations(i,state),cs=[...new Set(locs.map(l=>l.country))];return `<button class="card ${state.selected?.id===i.slug?'selected':''}" data-investor="${esc(i.slug)}"><strong>${esc(i.name)}</strong><small>${cs.map(c=>flag(c)).join(' ')} ${esc(cs.map(countryName).join(' · '))}</small><small>${esc(investorTypeOf(i))} · ${esc(i.evidenceStatusLabel||'Research record')} · ${locs.length} location${locs.length===1?'':'s'}</small></button>`}).join(''):'<div class="empty-card">No investors match this selection.<p class="muted">Try removing a filter or changing your search.</p><button data-reset>Clear filters</button></div>'}
function invPanel(i){if(!V)return '<div class="eyebrow">INVESTOR RESEARCH</div><h2>Records unavailable</h2><p class="muted">The investor export could not be loaded. Company data on this page is unaffected.</p><button data-retry-investors>Retry investor records</button>';if(!i)return '';let locs=i.locations||[],matched=investorLocations(i,state),stages=(i.stages||[]).map(normalizeLabel),focus=investorFocusOf(i),cav=V.caveats||{},o=[];
o.push(`<div class="eyebrow">INVESTOR / APPROVED RESEARCH RECORD</div><h2>${esc(i.name)}</h2><p class="muted">${esc(investorTypeOf(i))}${i.evidenceStatusLabel?' · '+esc(i.evidenceStatusLabel):''}</p>`);
if(!invResults().some(x=>x.slug===i.slug))o.push('<p class="notice">This investor is outside the current filters.</p>');
if(i.evidenceStatus==='mandate')o.push('<p class="muted">A stated mandate. No transaction is asserted by this record.</p>');
o.push(`<h3>Published locations</h3><ul class="plain">${locs.map(l=>`<li>${flag(l.country)} ${esc(l.city)}, ${esc(countryName(l.country))} — ${esc(kindLabel(l.kind))}${state.countries.length&&!matched.includes(l)?' <span class="muted">(outside the country filter)</span>':''}</li>`).join('')}</ul><p class="muted">${esc(cav.coordinates||'Approximate city centroids, not exact office locations.')} ${esc(cav.locationKinds||'')}</p>`);
o.push(stages.length?`<h3>Stages (as published)</h3>${stages.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}`:'<h3>Stages</h3><p class="muted">Not established.</p>');
if(focus.length)o.push(`<h3>Technology focus</h3>${focus.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}`);
if(i.ticket)o.push(`<h3>Published ticket range</h3><p>${esc(i.ticket.currency||'')} ${money(i.ticket.minimum)}–${money(i.ticket.maximum)}</p><p class="muted">${esc(i.ticket.basis||cav.tickets||'')}</p>${safeUrl(i.ticket.source)?`<a href="${esc(safeUrl(i.ticket.source))}" target="_blank" rel="noopener">Ticket source ↗</a>`:''}`);
if(i.selectedPortfolio?.length)o.push(`<h3>Selected portfolio</h3>${i.selectedPortfolio.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}<p class="muted">Named in published material. A portfolio mention is not a verified relationship to a similarly named company in this catalogue.</p>`);
if(i.legalDomicile?.country)o.push(`<h3>Legal registration</h3><p>${flag(i.legalDomicile.country)} ${esc(countryName(i.legalDomicile.country))}${i.legalDomicile.precision?` <span class="muted">(${esc(i.legalDomicile.precision)})</span>`:''}</p>${i.legalDomicile.note?`<p class="muted">${esc(i.legalDomicile.note)}</p>`:''}`);
if(i.investmentGeography?.length)o.push(`<h3>Stated investment geography</h3><p>${i.investmentGeography.map(x=>esc(x)).join(' · ')}</p><p class="muted">As published by the investor; separate from its office locations.</p>`);
if(i.countryAssociations?.length)o.push(`<h3>Country index</h3><p>${i.countryAssociations.map(c=>flag(c)+' '+esc(countryName(c))).join(' · ')}</p><p class="muted">${esc(cav.countryAssociations||'')}</p>`);
if(i.missingFields?.length)o.push(`<h3>Not established</h3><ul class="plain">${i.missingFields.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="muted">${esc(cav.emptyFields||'')}</p>`);
o.push(`<h3>Evidence</h3><p>${esc(i.evidenceStatusLabel||'Research record')}${i.verifiedAsOf?` · reviewed ${esc(i.verifiedAsOf)}`:''}</p>${(i.sources||[]).filter(x=>safeUrl(x.url)).map(x=>`<p><a href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener">${esc(x.title||x.url)} ↗</a></p>`).join('')||'<p class="muted">No source URL published.</p>'}`);
if(i.researchNote)o.push(`<h3>Research note</h3><p class="muted">${esc(i.researchNote)}</p>`);
if(V.membership)o.push(`<p class="muted">${esc(V.membership)}</p>`);
return o.join('')}
function renderInvestorMenus(){if(!invMode())return;let anyNoStage=!!V&&V.investors.some(i=>!(i.stages||[]).length),anyNoFocus=!!V&&V.investors.some(i=>!investorFocusOf(i).length),
types=V?[...new Set(V.investors.map(investorTypeOf))].sort((a,b)=>a.localeCompare(b)):[],
focus=V?[...new Set(V.investors.flatMap(investorFocusOf))].sort(byFocus):[],
menu=(sel,key,values,attr)=>{$(sel).innerHTML=V?(values.map(v=>`<label><input type="checkbox" data-${attr}="${esc(v)}" ${state[key].includes(v)?'checked':''}>${esc(v)}<span>${invFacet(key,v)}</span></label>`).join('')||'<p>No values published.</p>'):'<p>Investor records unavailable.</p>'};
menu('#typeMenu','investorTypes',types,'it');
menu('#stageMenu','investorStages',[...STAGE_LADDER,...(anyNoStage?[NOT_ESTABLISHED]:[])],'is');
menu('#focusMenu','investorFocus',[...focus,...(anyNoFocus?[NOT_ESTABLISHED]:[])],'if')}
async function loadInvestors(){vStatus='loading';if($('#investorStatus'))$('#investorStatus').textContent=invStatusText();let path=typeof D?.investors?.url==='string'&&D.investors.url?D.investors.url:'/data/landscape-investors.json',local=/^(www\.)?xsonomy\.com$/.test(location.hostname);try{V=await request(local?path:new URL(path,'https://xsonomy.com').href,validateInvestors);vStatus='ok'}catch{vStatus=V?'stale':'error'}}
load();
